function blurImage(img: number[][]): number[][] {
  const m = img.length, n = img[0].length;
  const out: number[][] = [];
  for (let i = 0; i < m; i++) {
    out.push(new Array(n).fill(0));
    for (let j = 0; j < n; j++) {
      let sum = 0, cnt = 0;
      for (let di = -1; di <= 1; di++)
        for (let dj = -1; dj <= 1; dj++) {
          const r = i + di, c = j + dj;
          if (r >= 0 && r < m && c >= 0 && c < n) { sum += img[r][c]; cnt++; }
        }
      out[i][j] = Math.floor(sum / cnt);
    }
  }
  return out;
}

