function blurImage(img: number[][]): number[][] {
  const m = img.length, n = img[0].length;
  const P: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) P[i + 1][j + 1] = img[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];
  const out: number[][] = [];
  for (let i = 0; i < m; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      const r1 = Math.max(0, i - 1), c1 = Math.max(0, j - 1);
      const r2 = Math.min(m - 1, i + 1), c2 = Math.min(n - 1, j + 1);
      const sum = P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
      row.push(Math.floor(sum / ((r2 - r1 + 1) * (c2 - c1 + 1))));
    }
    out.push(row);
  }
  return out;
}

